{
  "title": "Conversation Stats",
  "body": "<div class="panel">
  <h2>Conversation Stats</h2>
  <div class="sub" id="subline">computed live</div>
  <div class="section">
    <h3>Messages by role</h3>
    <div id="counts"></div>
  </div>
  <div class="section">
    <h3>5 most recent tool calls</h3>
    <ul id="tools"></ul>
  </div>
  <div class="section">
    <h3>Longest message</h3>
    <div class="big"><span id="longest">0</span> <small>chars</small></div>
  </div>
</div>",
  "css": ".panel { font-family: ui-sans-serif, system-ui, -apple-system, sans-serif; padding: 16px; background: #0f172a; color: #e2e8f0; border-radius: 12px; max-width: 340px; }
.panel h2 { margin: 0 0 2px; font-size: 15px; font-weight: 700; }
.sub { font-size: 12px; color: #94a3b8; margin-bottom: 6px; }
.section { margin-top: 14px; }
.section h3 { font-size: 11px; text-transform: uppercase; letter-spacing: .08em; color: #94a3b8; margin: 0 0 6px; font-weight: 600; }
.row { display: flex; justify-content: space-between; align-items: center; padding: 5px 10px; border-radius: 6px; background: #1e293b; margin-bottom: 4px; font-size: 13px; }
.role { font-weight: 600; }
.role-system { color: #f472b6; }
.role-user { color: #60a5fa; }
.role-assistant { color: #34d399; }
.role-tool { color: #fbbf24; }
.role-other { color: #c084fc; }
.num { font-variant-numeric: tabular-nums; color: #e2e8f0; }
ul#tools { margin: 0; padding-left: 18px; font-size: 13px; }
ul#tools li { padding: 2px 0; color: #e2e8f0; }
ul#tools li.empty { color: #64748b; font-style: italic; list-style: none; margin-left: -18px; }
.big { font-size: 24px; font-weight: 700; color: #34d399; font-variant-numeric: tabular-nums; }
.big small { font-size: 12px; color: #94a3b8; font-weight: 400; }",
  "scripts": [
    "const msgs = ml.current.messages ?? [];

// --- counts by role ---
const counts = {};
for (const m of msgs) {
  const r = m.role ?? 'unknown';
  counts[r] = (counts[r] ?? 0) + 1;
}

const countsEl = root.querySelector('#counts');
countsEl.replaceChildren();
const addRow = (role, n, cls) => {
  const row = root.create('div');
  row.classList.add('row');
  const label = root.create('span');
  label.classList.add('role');
  label.classList.add(cls);
  label.textContent = role;
  const val = root.create('span');
  val.classList.add('num');
  val.textContent = String(n);
  row.append(label);
  row.append(val);
  countsEl.append(row);
};
for (const role of ['system', 'user', 'assistant', 'tool']) {
  addRow(role, counts[role] ?? 0, 'role-' + role);
}
for (const r of Object.keys(counts)) {
  if (!['system', 'user', 'assistant', 'tool'].includes(r)) {
    addRow(r, counts[r], 'role-other');
  }
}

// --- five most recent tool calls (newest first) ---
const names = [];
for (const m of msgs) {
  for (const tc of (m.tool_calls ?? [])) {
    names.push(tc.function?.name ?? '(unnamed)');
  }
}
const last5 = names.slice(-5);
const recent = last5.map((_, i) => last5[last5.length - 1 - i]);

const toolsEl = root.querySelector('#tools');
toolsEl.replaceChildren();
if (recent.length === 0) {
  const li = root.create('li');
  li.classList.add('empty');
  li.textContent = '(no tool calls yet)';
  toolsEl.append(li);
} else {
  for (const n of recent) {
    const li = root.create('li');
    li.textContent = n;
    toolsEl.append(li);
  }
}

// --- longest message ---
const longest = msgs.reduce((a, m) => Math.max(a, String(m.content ?? '').length), 0);
root.querySelector('#longest').textContent = String(longest);

// --- subline ---
root.querySelector('#subline').textContent = msgs.length + ' messages total \u00b7 ' + names.length + ' tool calls \u00b7 live';"
  ]
}
```

The panel recomputes everything from `ml.current.messages` on every redraw (nothing is cached in `state`), so the role counts, five most recent tool call names (shown newest-first), and the longest-message length are always current. It also handles edge cases: zero tool calls, missing content, and unexpected roles beyond the standard four.
